    # nan check - if recent missing, keep prev
    if len(c_mid) < 60 or np.isnan(c_mid[-1]) or np.isnan(c_mid[-51]):
        raw = s['prev_C']
        return {'C': float(raw), 'A': 0.05, 'B': 0.15, 'IDX': 0.0, 'A.X': 0.0, 'B.X': 0.0, 'C.X': 0.0}
    # baseline long bias to capture drift (market up ~0.05 per step)
    baseline = 0.35
    # 50-step momentum
    past50 = float(c_mid[-1] - c_mid[-51])
    mom = 0.0
    if past50 > 6:
        mom = 0.45
    elif past50 > 2:
        mom = 0.20
    elif past50 < -6:
        mom = -0.45
    elif past50 < -2:
        mom = -0.20
    # imbalance signal - average last 5
    imb_val = float(np.nanmean(c_imb[-5:]))
    if np.isnan(imb_val):
        imb_sig = 0.0
    else:
        if imb_val > 0.45:
            imb_sig = 0.45
        elif imb_val > 0.25:
            imb_sig = 0.25
        elif imb_val < -0.45:
            imb_sig = -0.45
        elif imb_val < -0.25:
            imb_sig = -0.25
        else:
            imb_sig = 0.0
    # combine
    raw_desired = baseline + mom + imb_sig
    # clip
    if raw_desired > 1: raw_desired = 1
    if raw_desired < -1: raw_desired = -1
    # smooth to reduce turnover and improve Sharpe : EWMA 0.35
    prev = float(s['prev_C'])
    smoothed = 0.65 * prev + 0.35 * raw_desired
    # small deadband to avoid churn
    if abs(smoothed - prev) < 0.07:
        smoothed = prev
    # also avoid shorting too aggressively on strong up drift: floor at -0.3
    if smoothed < -0.3:
