    s['prev_C'] = float(smoothed)
    # keep other assets small long bias low turnover cheap venues, neutral expensive venues and IDX
    # A and B small baseline longs to add drift diversification with low cost (0 fee venues)
    # they also have momentum but weaker; we keep them static to avoid turnover
    return {'C': float(smoothed), 'A': 0.10, 'B': 0.15, 'IDX': 0.0, 'A.X': 0.0, 'B.X': 0.0, 'C.X': 0.0}

